parameters.jsCode:
// Extract structured payload sent by Streamlit Travel App
const data = $input.item.json.body || $input.item.json;

const destination = data.destination || 'Destination';
const origin = data.origin || 'Origin';
const duration = data.duration || 1;
const totalCost = data.total_estimated_cost || 0;
const userBudget = data.budget || 0;
const email = data.email || 'traveler@example.com';
const itinerary = data.itinerary || [];
const startDate = data.start_date || new Date().toISOString().split('T')[0];

// Generate formatted HTML summary for Gmail
let itineraryHtml = `<h2>✈️ Your Curated Travel Itinerary for ${destination}</h2>`;
itineraryHtml += `<p><b>Origin:</b> ${origin} | <b>Duration:</b> ${duration} Days | <b>Total Estimated Cost:</b> ₹${totalCost.toLocaleString('en-IN')}</p><hr/>`;

itinerary.forEach(day => {
  itineraryHtml += `<h3>Day ${day.day}${day.date ? ' (' + day.date + ')' : ''}: ${day.theme || 'Exploration'}</h3>`;
  itineraryHtml += `<p><b>🌅 Morning:</b> ${(day.morning || []).join(', ')}</p>`;
  itineraryHtml += `<p><b>☀️ Afternoon:</b> ${(day.afternoon || []).join(', ')}</p>`;
  itineraryHtml += `<p><b>🌙 Evening:</b> ${(day.evening || []).join(', ')}</p>`;
  if (day.notes) itineraryHtml += `<p><i>📌 Tips: ${day.notes}</i></p>`;
  itineraryHtml += `<br/>`;
});

return [{
  json: {
    ...data,
    calendar_event_summary: `Trip to ${destination} (${duration} Days)`,
    calendar_start_time: `${startDate}T09:00:00Z`,
    calendar_end_time: `${startDate}T19:00:00Z`,
    formatted_email_html: itineraryHtml,
    recipient_email: email
  }
}];

